<template>
 <div id="audio-music" role="tabpanel" aria-labelledby="audio-music-tab" class="music-editor" @keydown.stop="keyboard" tabindex="-1">
  <header class="music-heading"><div><span class="eyebrow">ISSD STUDIO / SPC700</span><h2>{{ $t('Estudio musical') }}</h2></div><label>{{ $t('Canción') }} <select :value="songName" @change="selectSong"><option v-for="r in resources" :key="r.id" :value="r.name">{{r.name}}</option></select></label></header>
  <p v-if="!resources.length" class="notice">{{ $t('Driver musical no compatible.') }}</p>
  <p class="help">{{ $t('Estudio musical de sólo lectura. Puedes explorar y escuchar las canciones o subir un archivo SPC para reproducirlo sin modificar la ROM.') }}</p>
  <div class="file-actions"><button :disabled="!song||!!externalSpc" @click="exportSpc">{{ $t('Exportar SPC') }}</button><label class="file-import">{{ $t('Subir archivo SPC') }}<input type="file" accept=".spc" @change="importFile" /></label></div>
  <p v-if="error" class="error" role="alert">{{ $t(error) }}</p>
  <MusicSpcPreview v-if="externalSpc" :key="externalSpc.version" :file="externalSpc" :filename="externalSpc.filename" @close="externalSpc=null" />
  <template v-if="resources.length">
   <div v-if="song&&!externalSpc" ref="stage" class="music-daw" :class="{maximized}">
    <MusicNavigator :tracks="tracks" :total="total" :start="viewStart" :span="viewSpan" :cursor="cursor" :colors="colors" @navigate="navigate" @seek="seek" @scrub-start="beginScrub" @scrub-end="finishScrub" />
    <div class="daw-toolbar">
     <div class="toolbar-group"><strong>PLAYLIST</strong><span class="badge">{{ song.tracks.length }} {{ $t('canales') }}</span><span class="badge">{{ $t('Sólo lectura') }}</span></div>
     <div class="toolbar-group"><button @click="zoomView(2)" :title="$t('Alejar')">−</button><label class="zoom-label">{{ $t('Zoom horizontal') }}<input type="range" min="12" max="240" :value="laneWidth/viewSpan*48" @input="setZoom(Number($event.target.value))" /></label><button @click="zoomView(.5)" :title="$t('Acercar')">＋</button><button @click="fitView">{{ $t('Ver canción completa') }}</button></div>
    </div>
    <MusicPlaylist v-show="!maximized" :tracks="tracks" :width="laneWidth" :start="viewStart" :span="viewSpan" :cursor="cursor" :channel="channel" :selected="selectedRegions" :solo="solo" @solo="toggleSolo" :editable="false" :snap="snap" :colors="colors" @select="selectRegion" @open="openRegion" @track="openTrack" @seek="seek" @scrub-start="beginScrub" @scrub-end="finishScrub" @pan="pan" @zoom="zoomView" />
    <div class="timeline-pan"><span>{{ $t('Posición temporal') }}</span><input type="range" min="0" :max="Math.max(0,total-viewSpan)" step="1" :value="viewStart" @input="navigate(Number($event.target.value))" :aria-label="$t('Desplazar línea de tiempo')" /><output>{{ position(cursor) }} · {{ $t(playbackState==='playing'?'Reproduciendo SPC700':'Posición de reproducción') }}</output></div>
    <template v-if="pianoOpen">
     <div class="panel-resizer" role="separator" tabindex="0" aria-orientation="horizontal" :aria-label="$t('Altura del Piano Roll')" :aria-valuemin="200" :aria-valuemax="680" :aria-valuenow="pianoHeight" @pointerdown="beginResize" @pointermove="resizePanel" @pointerup="resizeDrag=null" @pointercancel="resizeDrag=null" @keydown.up.stop.prevent="pianoHeight=Math.max(200,pianoHeight-24)" @keydown.down.stop.prevent="pianoHeight=Math.min(680,pianoHeight+24)"><span /></div>
     <header class="piano-heading"><div><strong :style="{color:colors[channel]}">PIANO ROLL</strong><select v-model.number="channel" @change="selection=[];selectedRegions=[]" :aria-label="$t('Canal')"><option v-for="t in song.tracks" :key="t.channel" :value="t.channel">{{ $t('Canal') }} {{t.channel+1}} · {{ $t('Instrumento') }} {{t.instrument}}</option></select></div><div><label>{{ $t('Zoom vertical') }} <input type="range" min="10" max="28" v-model.number="rowHeight" /></label><button @click="maximized=!maximized" :aria-label="$t(maximized?'Restaurar panel':'Maximizar Piano Roll')">{{ $t(maximized?'Restaurar panel':'Maximizar Piano Roll') }}</button><button @click="pianoOpen=false;maximized=false" :aria-label="$t('Cerrar Piano Roll')">×</button></div></header>
     <div ref="pianoPanel" class="piano-panel" :style="{height:maximized?'min(72vh,760px)':pianoHeight+'px'}"><MusicPianoRoll :track="track" :channel="channel" :selection="selection" :width="stageWidth" :start="viewStart" :span="viewSpan" :snap="snap" :row-height="rowHeight" :color="colors[channel]" :cursor="cursor" :editable="false" :read-only="true" tool="select" :scroll-top="pianoScroll[channel]" @select="selection=$event;selectedRegions=[]" @seek="seek" @scrub-start="beginScrub" @scrub-end="finishScrub" @scroll="pianoScroll[channel]=$event" @pan="pan" @zoom="zoomView" @pitch="selectPitch" /></div>
    </template>
    <button v-else class="open-piano" @click="pianoOpen=true">{{ $t('Abrir Piano Roll') }}</button>
    <div class="note-inspector"><span v-if="note">{{noteName(note.pitch)}} · {{position(note.tick)}} · {{ $t('Duración en ticks') }}: {{note.duration}} · {{ $t('Velocidad') }}: {{note.velocity}}</span><span class="bpm">{{song.bpm.toFixed(1)}} BPM · 48 PPQN · 4/4 {{ $t('de referencia') }}</span></div>
    <footer class="music-transport"><output>{{position(cursor)}}</output><div class="transport-icons"><button v-for="c in transportControls" :key="c.action" :disabled="transportDisabled(c.action)" :aria-pressed="c.action==='loop'?loopPreview:undefined" :aria-label="$t(c.label)" :title="$t(c.label)" @click="transport(c.action)"><svg viewBox="0 0 24 24"><path :d="c.path" /></svg></button></div><button v-if="solo!==null" @click="toggleSolo(solo)">{{ $t('Escuchar todos los canales') }} · {{ $t('Solo') }} {{solo+1}}</button><button @click="$router.push({name:'studio-emulator'})">{{ $t('Escuchar en Emulador') }}</button><span>{{ $t(playbackState==='loading'?'Preparando reproducción SPC…':playbackState==='playing'?'Reproduciendo SPC700':'Previsualización SPC de sólo lectura.') }}</span></footer>
   </div>
   <p v-if="song&&!externalSpc" class="help">{{ $t('Regiones visuales de hasta cuatro compases, derivadas de las notas. Shift permite selección múltiple; doble clic abre el Piano Roll. Ctrl/⌘ + rueda ajusta el zoom; Shift + rueda desplaza el tiempo.') }}</p>
  </template>
 </div>
</template>
<script>
import {musicResources,readMusic,decodeMusic} from '../rom/music.mjs';
import MusicSpcPreview from './MusicSpcPreview.vue';
import {inspectSpc} from '../rom/spc-preview.mjs';
import {writeSpc} from '../rom/music-spc.mjs';
import {musicRegions} from '../rom/music-score.mjs';
import MusicWorker from '../editor/music-playback-worker.mjs?worker';
import {MusicPlayback} from '../editor/music-playback.mjs';
import {AUDIO_TRANSPORT_CONTROLS} from '../editor/audio-transport.mjs';import {clamp,noteName,snapTick,zoomTimeline} from '../editor/timeline.mjs';
import MusicNavigator from './MusicNavigator.vue';import MusicPlaylist from './MusicPlaylist.vue';import MusicPianoRoll from './MusicPianoRoll.vue';
const COLORS=['#73c9ad','#baa2ef','#e0bb77','#75badd','#df94b7','#a1c979','#e59e73','#88a9f0'];
export default {
 components:{MusicSpcPreview,MusicNavigator,MusicPlaylist,MusicPianoRoll},props:{project:Object,revision:Number},
 data(){return {songName:'MainMenu',externalSpc:null,sequence:null,error:'',version:0,channel:0,selection:[],selectedRegions:[],cursor:0,viewStart:0,viewSpan:1536,stageWidth:900,rowHeight:18,pianoHeight:310,pianoOpen:true,maximized:false,pianoScroll:{},resizeDrag:null,observer:null,snap:1,colors:COLORS,transportControls:AUDIO_TRANSPORT_CONTROLS,playbackState:'stopped',loopPreview:false,solo:null,scrubbing:false,scrubResume:false};},
 computed:{rom(){this.revision;return this.project.bytes();},resources(){return musicResources(this.rom);},resource(){return this.resources.find(r=>r.name===this.songName);},song(){try{return this.sequence?decodeMusic(this.sequence):null;}catch{return null;}},track(){return this.song?.tracks[this.channel]||{notes:[]};},tracks(){return this.song?musicRegions(this.song):[];},note(){const ref=this.selection.length===1?this.selection[0]:null;return ref?this.song?.tracks[ref.channel]?.notes[ref.index]:null;},total(){return Math.max(768,...(this.song?.tracks.map(t=>Math.ceil((t.length+192)/192)*192)||[]));},laneWidth(){return Math.max(180,this.stageWidth-176);}},
 watch:{externalSpc(value){if(!value)this.$nextTick(()=>this.observe());},sequence(){this.stopPlayback();},revision(){this.reload(false);},project(){this.solo=null;this.reload();},total(){this.viewSpan=Math.min(this.total,this.viewSpan);this.navigate(this.viewStart);}},
 mounted(){this.reload();this.$nextTick(()=>this.observe());},beforeUnmount(){this.scrubResume=false;this.stopPlayback();this.saveUi();this.version++;this.observer?.disconnect();},
 methods:{
 async toggleSolo(channel){if(!Number.isInteger(channel)||!this.song?.tracks[channel])return;if(this._playback&&(this.playbackState==='playing'||this.playbackState==='paused'))this.cursor=this._playback.position()*this.song.bpm*48/60;this.stopPlayback();this.solo=this.solo===channel?null:channel;await this.playMusic();},
 beginScrub(){if(this.scrubbing)return;this.scrubResume=this.playbackState==='playing'||this.playbackState==='loading';this.scrubbing=true;this.stopPlayback();},
 finishScrub(){const resume=this.scrubResume;this.scrubbing=false;this.scrubResume=false;if(resume&&this.cursor<Math.max(...this.song.tracks.map(t=>t.length)))this.playMusic();},
 stopPlayback(){this._playback?.stop();this._playback=null;this.playbackState='stopped';},
 transportDisabled(action){return !this.song||(this.playbackState==='loading'&&action==='play')||(action==='pause'&&this.playbackState!=='playing');},
 async playMusic(){this.externalSpc=null;
  if(this.playbackState==='playing')return;
  if(this.playbackState==='paused'){try{await this._playback.resume();}catch(e){this.stopPlayback();this.error=e.message;}return;}
  this.error='';try{
   const secondsPerTick=60/this.song.bpm/48,end=Math.max(1,...this.song.tracks.map(t=>t.length));if(this.cursor>=end)this.cursor=0;
   const playback=new MusicPlayback({createWorker:()=>new MusicWorker(),onState:state=>{this.playbackState=state;},onError:error=>{this.error=error.message;},onPosition:seconds=>{this.cursor=Math.min(end,seconds/secondsPerTick);if(this.cursor<this.viewStart||this.cursor>this.viewStart+this.viewSpan)this.navigate(this.cursor-this.viewSpan*.15);if(seconds>=end*secondsPerTick&&this.loopPreview){this.cursor=0;this.playMusic();}}});this._playback=playback;
   await playback.play(writeSpc(this.rom,this.resource,this.sequence),this.cursor*secondsPerTick,end*secondsPerTick,this.solo);
  }catch(e){this.stopPlayback();this.error=e.message;}
 },
 async transport(action){try{if(action==='play')await this.playMusic();else if(action==='pause')await this._playback?.pause();else if(action==='stop'){this.stopPlayback();this.cursor=0;}else if(action==='loop')this.loopPreview=!this.loopPreview;else if(action==='start')this.seek(0);else if(action==='end'){this.stopPlayback();this.cursor=Math.max(...this.song.tracks.map(t=>t.length));}else this.seek(this.cursor+(action==='forward'?1:-1)*this.song.bpm*48/60);}catch(e){this.stopPlayback();this.error=e.message;}},
 noteName,
 position(tick){return `${Math.floor(tick/192)+1}.${Math.floor(tick%192/48)+1}.${String(Math.floor(tick%48)).padStart(2,'0')}`;},
 run(fn){this.error='';try{fn();}catch(e){this.error=e.message;}},
 observe(){if(!this.$refs.stage)return;this.observer?.disconnect();this.observer=new ResizeObserver(entries=>{this.stageWidth=Math.max(360,entries[0].contentRect.width);});this.observer.observe(this.$refs.stage);},
 uiKey(){return `issd-music-view:${this.project.hash}:${this.songName}`;},
 saveUi(){try{sessionStorage.setItem(this.uiKey(),JSON.stringify({channel:this.channel,cursor:this.cursor,viewStart:this.viewStart,viewSpan:this.viewSpan,rowHeight:this.rowHeight,pianoHeight:this.pianoHeight,pianoOpen:this.pianoOpen,pianoScroll:this.pianoScroll,maximized:this.maximized,selection:this.selection,selectedRegions:this.selectedRegions}));}catch{}},
 loadUi(){try{const saved=JSON.parse(sessionStorage.getItem(this.uiKey())||'null');if(!saved)return;for(const key of ['channel','cursor','viewStart','viewSpan','rowHeight','pianoHeight'])if(Number.isFinite(saved[key]))this[key]=saved[key];this.channel=clamp(Math.floor(this.channel),0,this.song.tracks.length-1);this.rowHeight=clamp(this.rowHeight,10,28);this.pianoHeight=clamp(this.pianoHeight,200,680);this.cursor=clamp(this.cursor,0,this.total);this.viewSpan=clamp(this.viewSpan,48,this.total);this.navigate(this.viewStart);if(Array.isArray(saved.selection))this.selection=saved.selection.filter(n=>Number.isInteger(n.channel)&&Number.isInteger(n.index)&&this.song.tracks[n.channel]?.notes[n.index]).slice(0,4096);if(Array.isArray(saved.selectedRegions)){const ids=new Set(this.tracks.flatMap(t=>t.regions.map(r=>r.id)));this.selectedRegions=saved.selectedRegions.filter(id=>ids.has(id));}if(typeof saved.pianoOpen==='boolean')this.pianoOpen=saved.pianoOpen;if(typeof saved.maximized==='boolean')this.maximized=saved.maximized;if(saved.pianoScroll&&typeof saved.pianoScroll==='object')this.pianoScroll=Object.fromEntries(Object.entries(saved.pianoScroll).filter(([key,value])=>/^\d$/.test(key)&&Number.isFinite(value)&&value>=0&&value<10000));}catch{}},
 reload(restoreView=true){this.externalSpc=null;this.scrubResume=false;this.scrubbing=false;this.stopPlayback();this.version++;this.sequence=null;this.error='';this.selection=[];this.selectedRegions=[];this.run(()=>{if(!this.resource)return;const m=readMusic(this.rom,this.resource);this.sequence=m.bytes;this.channel=Math.min(this.channel,m.tracks.length-1);if(restoreView)this.loadUi();this.$nextTick(()=>this.observe());});},
 selectSong(event){this.saveUi();this.songName=event.target.value;this.solo=null;this.channel=0;this.viewStart=0;this.viewSpan=1536;this.cursor=0;this.pianoScroll={};this.reload();},
 navigate(value){this.viewStart=clamp(value,0,Math.max(0,this.total-this.viewSpan));},
 pan(delta){this.navigate(this.viewStart+delta);},
 seek(tick){const playing=this.playbackState==='playing'||this.playbackState==='loading';this.stopPlayback();this.cursor=clamp(snapTick(tick,this.snap),0,this.total);if(playing&&this.cursor<Math.max(...this.song.tracks.map(t=>t.length)))this.playMusic();},
 zoomView(factor){const v=zoomTimeline({start:this.viewStart,span:this.viewSpan,total:this.total,minSpan:48,maxSpan:this.total},factor);this.viewSpan=v.span;this.viewStart=v.start;},
 setZoom(pixels){this.zoomView((this.laneWidth/this.viewSpan*48)/pixels);},
 fitView(){this.viewStart=0;this.viewSpan=this.total;},
 selectRegion({region,add}){this.channel=region.channel;if(add)this.selectedRegions=this.selectedRegions.includes(region.id)?this.selectedRegions.filter(id=>id!==region.id):[...this.selectedRegions,region.id];else if(!this.selectedRegions.includes(region.id))this.selectedRegions=[region.id];this.selection=this.tracks.flatMap(t=>t.regions.filter(r=>this.selectedRegions.includes(r.id)).flatMap(r=>r.notes.map(n=>({channel:n.channel,index:n.index}))));},
 openRegion(region){this.selectRegion({region,add:false});this.seek(region.start);this.pianoOpen=true;},
 openTrack(channel){this.channel=channel;this.selection=[];this.selectedRegions=[];this.pianoOpen=true;},
 selectPitch(pitch){this.selection=this.track.notes.flatMap((n,index)=>n.pitch===pitch?[{channel:this.channel,index}]:[]);},
 keyboard(e){if(this.externalSpc||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='Escape'){this.selection=[];this.selectedRegions=[];}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();this.selection=this.track.notes.map((_,index)=>({channel:this.channel,index}));}},
 beginResize(e){e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);this.resizeDrag={y:e.clientY,height:this.pianoHeight};},
 resizePanel(e){if(this.resizeDrag)this.pianoHeight=clamp(this.resizeDrag.height+e.clientY-this.resizeDrag.y,200,680);},
 exportSpc(){if(!this.song||this.externalSpc)return;this.run(()=>{const bytes=writeSpc(this.rom,this.resource,this.sequence),url=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download=`ISSD-${this.songName}.spc`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});},
 async importFile(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;const version=++this.version;this.error='';try{if(!/\.spc$/i.test(file.name))throw new Error('Selecciona un archivo SPC (.spc).');if(file.size>2000000)throw new Error('El archivo musical supera el límite de 2 MB.');const bytes=await file.arrayBuffer();if(version!==this.version)return;const preview=inspectSpc(bytes);this.scrubResume=false;this.scrubbing=false;this.stopPlayback();this.externalSpc={...preview,filename:file.name,version};}catch(e){if(version===this.version)this.error=e.message;}}
 }
};
</script>
<style scoped>
.music-editor{min-width:0;color:#dce8f4;background:#131c28;border:1px solid #34445a;border-radius:12px;padding:20px;font-size:13px}.music-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:16px}.eyebrow{color:#79c8b5;font-size:9px;letter-spacing:.2em}.music-heading h2{font-size:23px;margin:5px 0 0;letter-spacing:-.03em}.music-editor label{display:inline-flex;align-items:center;gap:7px}.music-editor button,.music-editor select,.music-editor input{font:inherit;box-sizing:border-box}.music-editor button,.music-editor select{background:#253448;color:#dce8f4;border:1px solid #42536b;border-radius:5px;padding:7px 9px;cursor:pointer}.music-editor button:hover:not(:disabled){background:#344b66;border-color:#7997ba}.music-editor button:disabled,.music-editor input:disabled{opacity:.35;cursor:default}.music-editor input[type=range]{accent-color:#80ccb6;height:16px}.music-editor button:focus-visible,.music-editor select:focus-visible,.music-editor input:focus-visible{outline:2px solid #a4d9ff;outline-offset:2px}.file-actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-bottom:14px}.file-import{padding:6px;border:1px dashed #526781;border-radius:5px}.file-import input{max-width:190px;font-size:10px}.music-daw{border:1px solid #37485d;border-radius:10px;overflow:hidden;min-width:0;background:#162131}.daw-toolbar,.piano-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;background:#202d3e;padding:8px 10px;border-bottom:1px solid #35465c}.toolbar-group{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.toolbar-group>strong,.piano-heading strong{font-size:10px;letter-spacing:.12em}.daw-toolbar button,.piano-heading button,.piano-heading select{padding:5px 7px;font-size:11px}.badge{font-size:9px;color:#a3cfba;border:1px solid #526b63;padding:3px 6px;border-radius:4px}.zoom-label{font-size:10px;color:#a9bdd3}.zoom-label input{width:90px}.timeline-pan{display:flex;gap:10px;align-items:center;padding:7px 12px;background:#192637;color:#9cb1ca;font-size:10px;border-bottom:1px solid #35465c}.timeline-pan input{flex:1;min-width:80px}.timeline-pan output{font:11px monospace;white-space:nowrap;color:#edca89}.panel-resizer{height:8px;display:flex;align-items:center;justify-content:center;background:#101925;cursor:ns-resize;touch-action:none}.panel-resizer span{width:44px;border-top:2px solid #546985}.panel-resizer:focus-visible{outline:2px solid #95ceff;outline-offset:-2px}.piano-heading>div{display:flex;align-items:center;gap:9px}.piano-heading label{font-size:10px;color:#a9bbd0}.piano-heading input{width:70px}.piano-panel{min-height:200px}.open-piano{display:block;margin:12px auto}.note-inspector{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:10px 12px;border-top:1px solid #35465c;background:#1b2839;color:#aebfd2;font-size:10px}.bpm{margin-left:auto;font:10px monospace;color:#98b7d1}.music-transport{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:#111b28;padding:10px 12px;border-top:1px solid #35465c}.music-transport output{font:17px monospace;color:#83c9f2;min-width:95px}.transport-icons{display:flex;gap:2px}.transport-icons button{width:25px;height:25px;padding:4px;background:transparent;border:0}.transport-icons button[aria-pressed=true]{background:#305b51;color:#a4f0d4}.transport-icons svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8}.music-transport>span{color:#879db6;font-size:10px;max-width:260px}.music-transport>button{font-size:11px}.help{font-size:11px;line-height:1.6;color:#9db0c9}.error{background:#542d37;color:#ffd4dc;border:1px solid #a05c6d;border-radius:5px;padding:10px;line-height:1.5}.notice{padding:14px;background:#3b3540;color:#edd8b1}.maximized .panel-resizer{display:none}@media(max-width:720px){.music-editor{padding:10px}.music-heading h2{font-size:19px}.music-heading label{max-width:100%}.daw-toolbar,.piano-heading{align-items:flex-start}.piano-heading>div{flex-wrap:wrap}.zoom-label input{width:65px}.music-transport{gap:6px}}
</style>
